# Hypothesis: TypeIs narrows both branches (the negative branch removes int from int | str) while TypeGuard narrows only the positive branch, and a gradual Any input narrowed by TypeIs keeps its runtime meaning.
from typing import Any, TypeGuard, TypeIs, assert_type, reveal_type


def is_int(v: object) -> TypeIs[int]:
    return isinstance(v, int)


def is_str_guard(v: object) -> TypeGuard[str]:
    return isinstance(v, str)


def is_pair[T](val: tuple[T, ...]) -> TypeIs[tuple[T, T]]:
    return len(val) == 2


def describe(v: int | str) -> str:
    if is_int(v):
        assert_type(v, int)
        return 'int'
    assert_type(v, str)
    return 'str'


def describe_guard(v: int | str) -> str:
    if is_str_guard(v):
        assert_type(v, str)
        return 'str'
    reveal_type(v)
    return 'other'


class Node:
    def __init__(self, label: int | str) -> None:
        self.label = label


def use_node(n: Node) -> str:
    if is_int(n.label):
        assert_type(n.label, int)
        return 'num'
    reveal_type(n.label)
    return 'text'


def dict_num(d: dict[str, int | str]) -> int:
    if is_int(d['k']):
        return d['k'] + 1
    return 0


def from_raw(raw: Any) -> str:
    if is_int(raw):
        reveal_type(raw)
        return 'int'
    return 'other'


def pair_sum(v: tuple[int, ...]) -> int:
    if is_pair(v):
        assert_type(v, tuple[int, int])
        return v[0] + v[1]
    return sum(v)


assert describe(3) == 'int'
assert describe('x') == 'str'
assert describe_guard(3) == 'other'
assert describe_guard('x') == 'str'
assert use_node(Node(5)) == 'num'
assert use_node(Node('a')) == 'text'
assert dict_num({'k': 4}) == 5
assert from_raw(1) == 'int'
assert from_raw('s') == 'other'
assert pair_sum((1, 2)) == 3
assert pair_sum((1, 2, 3)) == 6
